import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:zagents/services/file_system_service.dart';

/// Password-protected unzip support: real interop fixtures generated by
/// scripts/make_zip_fixtures.py — zipcrypto.zip was verified against the
/// Python stdlib zipfile reader and aes256.zip against pyzipper (WinZip
/// compatible AES-256). Both carry the same throwaway test password.
void main() {
  const String password = 'fixt-pass-42';
  const String hello =
      'Hello from an encrypted zip! ZAgents can decrypt this.\n';
  const String info =
      '# Encrypted fixture\nThis entry sits in a nested folder.\n';

  late Directory tempDir;
  late FileSystemService fs;

  setUp(() async {
    tempDir = await Directory.systemTemp.createTemp('zagents_zip_pw_test');
    fs = FileSystemService(resolveBaseDir: () async => tempDir);
  });

  tearDown(() async {
    if (await tempDir.exists()) await tempDir.delete(recursive: true);
  });

  /// Copies a committed fixture into the sandbox as uploads/<name>.
  Future<String> installFixture(String name) async {
    final Directory uploads = Directory('${tempDir.path}/uploads');
    await uploads.create(recursive: true);
    final File fixture = File('test/fixtures/$name');
    final String dest = '${uploads.path}/$name';
    await fixture.copy(dest);
    return 'uploads/$name';
  }

  group('ZipCrypto (legacy password encryption)', () {
    test('without password throws ZipPasswordRequiredException', () async {
      final String rel = await installFixture('zipcrypto.zip');
      await expectLater(
        fs.unzip(rel),
        throwsA(isA<ZipPasswordRequiredException>()),
      );
    });

    test('wrong password throws ZipWrongPasswordException', () async {
      final String rel = await installFixture('zipcrypto.zip');
      await expectLater(
        fs.unzip(rel, password: 'wrong'),
        throwsA(isA<ZipWrongPasswordException>()),
      );
    });

    test('correct password extracts nested entries byte-exact', () async {
      final String rel = await installFixture('zipcrypto.zip');
      final String dest = await fs.unzip(rel, password: password);
      expect(dest, 'uploads/zipcrypto');
      expect(
        await File('${tempDir.path}/$dest/hello.txt').readAsString(),
        hello,
      );
      expect(
        await File('${tempDir.path}/$dest/data/info.md').readAsString(),
        info,
      );
    });
  });

  group('WinZip AES-256 (AE-2)', () {
    test('without password throws ZipPasswordRequiredException', () async {
      final String rel = await installFixture('aes256.zip');
      await expectLater(
        fs.unzip(rel),
        throwsA(isA<ZipPasswordRequiredException>()),
      );
    });

    test('wrong password throws ZipWrongPasswordException', () async {
      final String rel = await installFixture('aes256.zip');
      await expectLater(
        fs.unzip(rel, password: 'nope'),
        throwsA(isA<ZipWrongPasswordException>()),
      );
    });

    test('correct password extracts nested entries byte-exact', () async {
      final String rel = await installFixture('aes256.zip');
      final String dest = await fs.unzip(rel, password: password);
      expect(
        await File('${tempDir.path}/$dest/hello.txt').readAsString(),
        hello,
      );
      expect(
        await File('${tempDir.path}/$dest/data/info.md').readAsString(),
        info,
      );
    });

    test('destName is still honored alongside the password', () async {
      final String rel = await installFixture('aes256.zip');
      final String dest = await fs.unzip(
        rel,
        destName: 'out',
        password: password,
      );
      expect(dest, 'uploads/out');
      expect(
        await File('${tempDir.path}/uploads/out/hello.txt').readAsString(),
        hello,
      );
    });
  });

  test('plain zips keep extracting without a password (regression)', () async {
    // Build an unencrypted archive through the same service, then extract
    // it — the password refactor must not disturb the plain path.
    final File plain = File('${tempDir.path}/plain.txt');
    await plain.writeAsString('nothing secret here');
    final String zipRel = await fs.zip('plain.txt');
    final String dest = await fs.unzip(zipRel);
    expect(
      await File('${tempDir.path}/$dest/plain.txt').readAsString(),
      'nothing secret here',
    );
    // And supplying a password to a plain zip is harmless.
    final String dest2 = await fs.unzip(
      zipRel,
      destName: 'again',
      password: 'x',
    );
    expect(
      await File('${tempDir.path}/$dest2/plain.txt').readAsString(),
      'nothing secret here',
    );
  });
}
